  const companyLogoBase64 = "data:image/png;base64,";


document.getElementById('cart-summary')?.addEventListener('click', () => {
  window.location.href = "cart.html";
});

let cart = JSON.parse(localStorage.getItem('cart')) || [];

// Utility to clean numbers
function cleanText(value) {
  return String(value)
    .replace(/[^\w\s\-\(\)\/]/g, "") // keep letters, numbers, spaces, (), -, /
    .trim();
}

function cleanNumber(value) {
  const num = String(value).replace(/[^0-9.]/g, "");
  return parseFloat(num) || 0;
}

function formatINR(value) {
  const num = cleanNumber(value);
  return `Rs. ${num.toLocaleString("en-IN", { minimumFractionDigits: 2 })}`;
}

function updateCartDisplay() {
  const totalItems = cart.reduce((sum, item) => sum + (item.qty || 1), 0);
  const totalAmount = cart.reduce((sum, item) => sum + Number(item.price) * (item.qty || 1), 0);
  const summary = document.getElementById('cart-summary');
  if (summary) {
    summary.innerHTML = `🛍️ View Cart (${cart.length} products, ${totalItems} items) - ₹${totalAmount.toFixed(2)}`;
  }
  localStorage.setItem('cart', JSON.stringify(cart));
}

function renderCartTable() {
  const tbody = document.getElementById('cart-items');
  if (!tbody) return;

  tbody.innerHTML = cart.map((item, index) => `
    <tr>
      <td>${item.name}</td>
      <td>${item.variant || "-"}</td>
      <td>₹${Number(item.price).toFixed(2)}</td>
      <td>
        <button class="qty-btn" onclick="changeQty(${index}, -1)">−</button>
        ${item.qty}
        <button class="qty-btn" onclick="changeQty(${index}, 1)">+</button>
      </td>
      <td>₹${(Number(item.price) * item.qty).toFixed(2)}</td>
      <td><button class="remove-btn" onclick="removeItem(${index})">Remove</button></td>
    </tr>
  `).join('');

  const total = cart.reduce((sum, i) => sum + Number(i.price) * i.qty, 0);
  document.getElementById('cart-total').innerText = `₹${total.toFixed(2)}`;
}

// Toast notification
function showToast(message, type="info") {
  const container = document.getElementById('toast-container');
  if (!container) return;
  const toast = document.createElement('div');
  toast.className = `toast ${type}`;
  toast.innerText = message;
  container.appendChild(toast);

  setTimeout(() => toast.classList.add('show'), 100);
  setTimeout(() => {
    toast.classList.remove('show');
    setTimeout(() => toast.remove(), 300);
  }, 3000);
}

function changeQty(index, delta) {
  cart[index].qty += delta;
  if (cart[index].qty <= 0) {
    showToast(`${cart[index].name} removed from cart`, "error");
    cart.splice(index, 1);
  } else {
    showToast(`${cart[index].name} quantity updated`, "success");
  }
  updateCartDisplay();
  renderCartTable();
}

function removeItem(index) {
  showToast(`${cart[index].name} removed from cart`, "error");
  cart.splice(index, 1);
  updateCartDisplay();
  renderCartTable();
}

document.addEventListener('DOMContentLoaded', () => {
  cart = cart.map(item => ({ ...item, qty: item.qty || 1 }));
  updateCartDisplay();
  renderCartTable();

  const form = document.getElementById('orderForm');
  if (form) {
    form.addEventListener('submit', e => {
      e.preventDefault();
	if (!cart || cart.length === 0) {
    	   // Show toast warning instead of alert
    	   showToast("⚠️ No items in the cart. Please add products before placing an order.", "error");
    	   return;
  	}
      const details = {
        name: document.getElementById('name').value,
        address: document.getElementById('address').value,
        city: document.getElementById('city').value,
        state: document.getElementById('state').value,
        zip: document.getElementById('zip').value,
        phone: document.getElementById('phone').value
      };

      const message = `New Order from ${details.name}%0A${details.address}, ${details.city}, ${details.state} - ${details.zip}%0A📞 ${details.phone}%0A%0AItems:%0A` +
        cart.map(item => `${item.name} (${item.variant || "-"}) x${item.qty} - ₹${(Number(item.price) * item.qty).toFixed(2)}`).join('%0A') +
        `%0A%0ATotal: ₹${cart.reduce((sum, i) => sum + Number(i.price) * i.qty, 0).toFixed(2)}%0A------------------------------%0A`;

      // Export to Excel
      //exportOrderToExcel(details, cart);

      // Export to PDF
      exportOrderToPDF(details, cart);

      window.open(`https://wa.me/${SHOP_NUMBER}?text=${message}`, '_blank');

      const successDiv = document.createElement('div');
      successDiv.className = "order-success";
      successDiv.innerHTML = `
  <h2>🎉 Order Successfully Placed!</h2>
  <p>We will reach out to you shortly for shipping charges and payment details.</p>
  <p class="share-note">📱 Please share the generated PDF invoice with us on WhatsApp +91-98436 11870 — that will help us get back to you quickly.</p>
  <button onclick="window.location.href='products.html'" class="continue-btn">Continue Shopping</button>
 
`;
	// <button id="clearCartBtn" class="clear-btn">Clear Cart</button>
      form.replaceWith(successDiv);

      showToast("Order placed successfully", "success");

      //document.getElementById('clearCartBtn').addEventListener('click', () => {
        cart = [];
        localStorage.removeItem('cart');
        updateCartDisplay();
        renderCartTable();
        document.getElementById('cart-items').innerHTML = "<tr><td colspan='6'>Your cart is now empty.</td></tr>";
        //showToast("Cart cleared successfully", "info");
      //});
    });
  }

  // Add to Cart button handler
  document.querySelectorAll('.add-to-cart').forEach(btn => {
    btn.addEventListener('click', () => {
      const name = btn.dataset.name;
      const variant = btn.dataset.variant || "-";
      const price = cleanNumber(btn.dataset.price);
      const existingItem = cart.find(item => item.name === name && item.variant === variant);
      if (existingItem) {
        existingItem.qty += 1;
      } else {
        cart.push({ name, variant, price, qty: 1 });
      }

      updateCartDisplay();

      btn.classList.add("added");
      btn.innerHTML = `<i class="fa fa-check"></i> Added!`;
      setTimeout(() => {
        btn.classList.remove("added");
        btn.innerHTML = `<i class="fa fa-cart-plus"></i> Add to Cart`;
      }, 1500);

      showToast(`${name} (${variant}) added to cart`, "success");

      const cartSummary = document.getElementById('cart-summary');
      if (cartSummary) {
        cartSummary.classList.add("shake");
        setTimeout(() => cartSummary.classList.remove("shake"), 500);
      }
    });
  });
});

// Export order to Excel
function exportOrderToExcel(customer, cart) {
  const wb = XLSX.utils.book_new();

  const customerSheet = XLSX.utils.json_to_sheet([customer]);
  XLSX.utils.book_append_sheet(wb, customerSheet, "Customer Details");

  const orderItems = cart.map(item => ({
    Product: item.name,
    Variant: item.variant || "-",
    Price: Number(item.price).toFixed(2),
    Quantity: item.qty,
    Subtotal: (Number(item.price) * item.qty).toFixed(2)
  }));

  const grandTotal = cart.reduce((sum, i) => sum + Number(i.price) * i.qty, 0).toFixed(2);
  orderItems.push({ Product: "Grand Total", Variant: "", Price: "", Quantity: "", Subtotal: grandTotal });
  orderItems.push({ Product: "------------------------------", Variant: "", Price: "", Quantity: "", Subtotal: "" });
  orderItems.push({ Product: "✨ Thanks for shopping with us! ✨", Variant: "", Price: "", Quantity: "", Subtotal: "" });

  const orderSheet = XLSX.utils.json_to_sheet(orderItems);
  XLSX.utils.book_append_sheet(wb, orderSheet, "Order Items");

  const now = new Date();
  const options = { day: "2-digit", month: "short", year: "numeric" };
  const formattedDate = now.toLocaleDateString("en-GB", options).replace(/ /g, "");
  const safeName = customer.name.replace(/\s+/g, "");
  const filename = `OrderFrom${safeName}${formattedDate}.xlsx`;

  XLSX.writeFile(wb, filename);
}

function exportOrderToPDF(customer, cart) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF();



// --- Order Items Table (start closer) ---
const now = new Date();
const options = { day: "2-digit", month: "short", year: "numeric" };
const formattedDate = now.toLocaleDateString("en-GB", options);

doc.autoTable({
  head: [["Product", "Size/Variant", "Price (Rs.)", "Quantity", "Subtotal (Rs.)"]],
  body: cart.map(item => [
    cleanText(item.name),
    cleanText(item.variant || "-"),
    formatINR(item.price),
    item.qty,
    formatINR(cleanNumber(item.price) * item.qty)
  ]),
  styles: { fontSize: 11 },
  headStyles: { fillColor: [139, 94, 60], textColor: [255, 255, 255] },
  columnStyles: {
    2: { halign: "right" },
    3: { halign: "center" },
    4: { halign: "right" }
  },
  margin: { top: 57 }, // reserve space for header (same on all pages)
  didDrawPage: function (data) {
    // --- Top Row: Title + Date ---
    doc.setFontSize(15);
    doc.setTextColor(0, 0, 0);
    doc.text("Order Invoice", doc.internal.pageSize.getWidth() / 2, 15, { align: "center" });

    doc.setFontSize(11);
    doc.text(`Date: ${formattedDate}`, doc.internal.pageSize.getWidth() - 14, 15, { align: "right" });

    // --- Header Background Bar ---
    doc.setFillColor(212, 175, 55);
    doc.rect(10, 20, 190, 35, "F");

    // --- Logo (left) ---
    //doc.addImage(companyLogoBase64, "PNG", 14, 26, 18, 18); // smaller, tighter
    doc.addImage(companyLogoBase64, "PNG", 14, 22, 35, 35); // larger logo


    // --- Shop details (center) ---
    doc.setFontSize(12);
    doc.setTextColor(255, 255, 255);
    doc.text("Malaiyamman Traders – Crackers & Fireworks", 85, 28, { align: "center" });
    doc.text("123 Market Street, Trivandrum, Kerala", 85, 34, { align: "center" });
    doc.text("Phone: +91-9843611870", 85, 40, { align: "center" });

    // --- Customer details (right) ---
    doc.setFontSize(11);
    const custLinesRaw = [
  `Customer Details:`,
  `${customer.name}`,  
  `${customer.city}`, 
  `${customer.state} - ${customer.zip}`,
  `Phone: ${customer.phone}`,
];
custLinesRaw.forEach((line, i) => {
  const wrapped = doc.splitTextToSize(line, 80); // 80px width for right column
  wrapped.forEach((wLine, j) => {
    doc.text(wLine, 190, 28 + (i * 6) + (j * 6), { align: "right" });
  });
});


    // --- Separator Line ---
    //doc.setDrawColor(255, 255, 255);
    //doc.setLineWidth(0.5);
    //doc.line(10, 57, 200, 57);

    // --- Page Footer with Page Numbers ---
    const pageCount = doc.internal.getNumberOfPages();
    doc.setFontSize(10);
    doc.setTextColor(100);
    doc.text(
      `Page ${data.pageNumber} of ${pageCount}`,
      doc.internal.pageSize.getWidth() / 2,
      doc.internal.pageSize.getHeight() - 10,
      { align: "center" }
    );
  }
});



  // --- Total ---
  const totalAmount = cart.reduce((sum, i) => sum + cleanNumber(i.price) * i.qty, 0);
  const finalY = doc.lastAutoTable.finalY + 15;
  doc.setFontSize(14);  
  doc.text(`Total Amount: ${formatINR(totalAmount)}`, 200, finalY, { align: "right" });

  // --- Footer Separator + Message ---
  const footerY = finalY + 20;
  doc.setDrawColor(139, 94, 60);
  doc.setLineWidth(0.5);
  doc.line(14, footerY - 5, 195, footerY - 5);

  doc.setFontSize(12);
  doc.setTextColor(139, 94, 60);
  doc.text(" Thanks for shopping with us! ", 105, footerY, { align: "center" });

  // --- Filename ---
  //const formattedDate = now.toLocaleDateString("en-GB", options).replace(/ /g, "");
  const safeName = customer.name.replace(/\s+/g, "");
  const filename = `OrderFrom${safeName}${formattedDate}.pdf`;

  doc.save(filename);
}


// Global Clear Cart button handler (page-level heading button)
const clearCartBtn = document.getElementById('clearCartBtn');
if (clearCartBtn) {
  clearCartBtn.addEventListener('click', () => {
    cart = [];
    localStorage.removeItem('cart');
    updateCartDisplay();
    renderCartTable();
    document.getElementById('cart-items').innerHTML = "<tr><td colspan='6'>Your cart is now empty.</td></tr>";
    showToast("Cart cleared successfully", "info");
  });
}

document.getElementById("phone").addEventListener("input", function () {
  this.value = this.value.replace(/\D/g, ""); // remove non-digits
});

document.getElementById("zip").addEventListener("input", function () {
  this.value = this.value.replace(/\D/g, ""); // remove non-digits
});


